command:
cat > /root/certrotate/roles/https_cert_rotate/templates/nginx-8443.conf.j2 <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/certs/server.crt;
    ssl_certificate_key /etc/nginx/certs/server.key;

    location / {
        default_type text/plain;
        return 200 "ok\n";
    }
}
EOF

cat > /root/certrotate/roles/https_cert_rotate/templates/cert-renew.service.j2 <<'EOF'
[Unit]
Description=Renew self-signed HTTPS certificate for nginx on port 8443
After=network.target

[Service]
Type=oneshot
ExecStart=/usr/local/bin/renew-https-cert.sh
EOF

cat > /root/certrotate/roles/https_cert_rotate/templates/cert-renew.timer.j2 <<'EOF'
[Unit]
Description=Periodic check/renewal of HTTPS certificate for nginx on port 8443

[Timer]
OnBootSec=30s
OnUnitActiveSec={{ https_cert_check_interval_seconds }}s
AccuracySec=5s
Persistent=true

[Install]
WantedBy=timers.target
EOF
echo done

